/**
 * Next per-project issue number: one past the highest number the project has
 * ever issued. Archived issues keep their number, and a number whose issue
 * moved away is retired, so the rows alone cannot answer that question.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return highestIssuedNumber(orgId, projectId) + 1;
}

/**
 * The highest number a project has issued. The sequence row is the record; the
 * row maximum is kept as a floor so a project written before the sequence
 * existed, or through a path that skipped it, is never handed a used number.
 */
function highestIssuedNumber(orgId: OrgId, projectId: ProjectId): number {
  const sequence = getDb()
    .select({ value: issueNumberSequences.lastIssued })
    .from(issueNumberSequences)
    .where(
      and(
        orgPredicate(issueNumberSequences.orgId, orgId),
        eq(issueNumberSequences.projectId, projectId),
      ),
    )
    .get();

  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  return Math.max(sequence?.value ?? 0, row?.value ?? 0);
}

/** Records that `issueNumber` was issued in `projectId`. The mark never goes down. */
function recordIssuedNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  getDb()
    .insert(issueNumberSequences)
    .values({ orgId, projectId, lastIssued: issueNumber })
    .onConflictDoUpdate({
      target: issueNumberSequences.projectId,
      set: {
        lastIssued: sql`max(${issueNumberSequences.lastIssued}, ${issueNumber})`,
      },
    })
    .run();
}

