/**
 * Files an issue under `toProjectId` with the number that project would hand a
 * new issue, and retires the number the issue carried. Everything up to the
 * update is synchronous, so no other write can take the target number in
 * between; the label read afterwards only shapes the returned row.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const current = getDb()
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  if (!current) throw new Error(`Issue ${issueId} not found`);

  const from = toIssue(current);
  recordIssuedNumber(orgId, from.projectId, from.number);

  const number = highestIssuedNumber(orgId, toProjectId) + 1;
  const row = getDb()
    .update(issues)
    .set({
      projectId: toProjectId,
      number,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  recordIssuedNumber(orgId, toProjectId, number);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

