/**
 * "Move to project" — the rules in docs/adr/0011-moving-issues-between-projects.md:
 * numbering, both permission checks, the quota, the single event, the audit row
 * and the search index.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** A second project in the tenant; key and slug must be unique per org. */
async function newProject(t: Tenant, slug: string, key: string): Promise<Project> {
  return projectRepo.insertProject({
    orgId: t.org.id,
    name: slug,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function createIn(
  t: Tenant,
  projectId: ProjectId,
  title: string,
  assigneeId: Issue["assigneeId"] = null,
): Promise<Issue> {
  return issueService.createIssue(
    t.actors.member,
    issueInput(t.org.id, projectId, { title, assigneeId }),
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movesvc");
  detachers.push(
    searchService.registerSearchListeners(),
    activityService.registerActivityListeners(),
  );
});

afterEach(() => {
  while (detachers.length > 1) detachers.pop()?.();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("issue-service — moveIssueToProject", () => {
  it("re-files the issue under the target's next number and keeps its content", async () => {
    const source = await newProject(tenant, "content-source", "CSO");
    const dest = await newProject(tenant, "content-dest", "CDS");
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "content-label",
      color: "#ef4444",
      description: null,
    });
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, source.id, {
        title: "Keep every field",
        assigneeId: tenant.userIds.admin,
      }),
      description: "Body text",
      status: "in_progress",
      priority: "high",
      estimate: 5,
      labelIds: [label.id],
    });

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: dest.id,
    });

