/**
 * "Move to project" — the rules in docs/adr/0011-moving-issues-between-projects.md:
 * numbering, both permission checks, the quota, the single event, the audit row
 * and the search index.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as activityService from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** A second project in the tenant; key and slug must be unique per org. */
async function newProject(t: Tenant, slug: string, key: string): Promise<Project> {
  return projectRepo.insertProject({
    orgId: t.org.id,
    name: slug,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function createIn(
  t: Tenant,
  projectId: ProjectId,
  title: string,
  assigneeId: Issue["assigneeId"] = null,
): Promise<Issue> {
  return issueService.createIssue(
    t.actors.member,
    issueInput(t.org.id, projectId, { title, assigneeId }),
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movesvc");
  detachers.push(
    searchService.registerSearchListeners(),
    activityService.registerActivityListeners(),
  );
});

afterEach(() => {
  while (detachers.length > 1) detachers.pop()?.();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("issue-service — moveIssueToProject", () => {
  it("re-files the issue under the target's next number and keeps its content", async () => {
    const source = await newProject(tenant, "content-source", "CSO");
    const dest = await newProject(tenant, "content-dest", "CDS");
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "content-label",
      color: "#ef4444",
      description: null,
    });
    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, source.id, {
        title: "Keep every field",
        assigneeId: tenant.userIds.admin,
      }),
      description: "Body text",
      status: "in_progress",
      priority: "high",
      estimate: 5,
      labelIds: [label.id],
    });

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: dest.id,
    });

    expect(moved).toMatchObject({
      id: issue.id,
      projectId: dest.id,
      number: 1,
      title: "Keep every field",
      description: "Body text",
      status: "in_progress",
      priority: "high",
      assigneeId: tenant.userIds.admin,
      estimate: 5,
      labelIds: [label.id],
    });
    await expect(issueRepo.countIssues(tenant.org.id, dest.id)).resolves.toBe(1);
    await expect(issueRepo.countIssues(tenant.org.id, source.id)).resolves.toBe(0);
  });

  it("retires the number the issue carried, so the source never issues it again", async () => {
    const source = await newProject(tenant, "retire-source", "RTS");
    const dest = await newProject(tenant, "retire-dest", "RTD");
    await createIn(tenant, source.id, "first");
    const second = await createIn(tenant, source.id, "second");

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: second.id,
      toProjectId: dest.id,
    });

    const next = await createIn(tenant, source.id, "third");
    expect(next.number).toBe(3);
  });

  it("gives a moved-back issue a fresh number rather than its old one", async () => {
    const source = await newProject(tenant, "back-source", "BKS");
    const dest = await newProject(tenant, "back-dest", "BKD");
    const issue = await createIn(tenant, source.id, "round trip");
    await createIn(tenant, source.id, "bystander");

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: dest.id,
    });
    const back = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: source.id,
    });

    expect(back.projectId).toBe(source.id);
    expect(back.number).toBe(3);
  });

  it("does nothing and publishes nothing when the target is the project it is already in", async () => {
    const issue = await createIn(tenant, tenant.project.id, "stays put");
    const moved = capture("issue.moved");
    const updated = capture("issue.updated");

    const result = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: tenant.project.id,
    });

    expect(result).toEqual(issue);
    expect(moved).toHaveLength(0);
    expect(updated).toHaveLength(0);
  });

  it("refuses an actor without issue:update and changes nothing", async () => {
    const source = await newProject(tenant, "viewer-source", "VWS");
    const dest = await newProject(tenant, "viewer-dest", "VWD");
    const issue = await createIn(tenant, source.id, "not yours to move");

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: dest.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.projectId).toBe(source.id);
  });

  it("also requires issue:create in the target, even for someone who may edit the issue", async () => {
    const source = await newProject(tenant, "dual-source", "DUS");
    const dest = await newProject(tenant, "dual-dest", "DUD");
    // A viewer may edit an issue assigned to them, but may not create one.
    const issue = await createIn(tenant, source.id, "assigned to a viewer", tenant.userIds.viewer);

    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: dest.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.projectId).toBe(source.id);
  });

  it("refuses a target that is already at its plan's issue quota", async () => {
    const cramped = await createTenant("movequota", "free");
    const source = cramped.project;
    const full = await newProject(cramped, "full-target", "FUL");
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(cramped.org.id, full.id, { title: `Seed ${number}` }),
        cramped.userIds.member,
        number,
      );
    }
    const issue = await createIn(cramped, source.id, "one too many");

    await expect(
      issueService.moveIssueToProject(cramped.actors.member, {
        orgId: cramped.org.id,
        issueId: issue.id,
        toProjectId: full.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    const stored = await issueRepo.findIssueById(cramped.org.id, issue.id);
    expect(stored?.projectId).toBe(source.id);
    expect(stored?.number).toBe(1);
  });

  it("refuses a project from another workspace, and a caller from another workspace", async () => {
    const other = await createTenant("moveother");
    const source = await newProject(tenant, "scope-source", "SCS");
    const issue = await createIn(tenant, source.id, "scoped");

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: other.project.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.moveIssueToProject(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: source.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("refuses an archived issue, and an archived target project", async () => {
    const source = await newProject(tenant, "archive-source", "ARS");
    const dest = await newProject(tenant, "archive-dest", "ARD");
    const issue = await createIn(tenant, source.id, "already archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: dest.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const live = await createIn(tenant, source.id, "live issue");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: dest.id,
      archiveIssues: false,
    });

    await expect(
      issueService.moveIssueToProject(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: live.id,
        toProjectId: dest.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("emits one issue.moved on behalf of the actor, with both projects and both numbers", async () => {
    const source = await newProject(tenant, "event-source", "EVS");
    const dest = await newProject(tenant, "event-dest", "EVD");
    const issue = await createIn(tenant, source.id, "announce me");

    const moved = capture("issue.moved");
    const created = capture("issue.created");
    const updated = capture("issue.updated");
    const archived = capture("issue.archived");

    await issueService.moveIssueToProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: dest.id,
    });

    expect(moved).toHaveLength(1);
    expect(moved[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      issueId: issue.id,
      fromProjectId: source.id,
      toProjectId: dest.id,
      fromNumber: 1,
      toNumber: 1,
    });
    expect(created).toHaveLength(0);
    expect(updated).toHaveLength(0);
    expect(archived).toHaveLength(0);
  });

  it("writes one audit row under the target project and leaves earlier rows where they were", async () => {
    const source = await newProject(tenant, "audit-source", "AUS");
    const dest = await newProject(tenant, "audit-dest", "AUD");
    const issue = await createIn(tenant, source.id, "audit me");

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: dest.id,
    });

    const moves = await activityService.listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["issue.moved"],
      limit: 100,
      cursor: null,
    });
    const move = moves.items.find((event) => event.subjectId === issue.id);
    expect(move).toMatchObject({
      action: "issue.moved",
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: dest.id,
      metadata: {
        fromProjectId: source.id,
        toProjectId: dest.id,
        fromNumber: 1,
        toNumber: 1,
      },
    });

    const created = await activityService.listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 100,
      cursor: null,
    });
    const original = created.items.find((event) => event.subjectId === issue.id);
    expect(original?.projectId).toBe(source.id);
  });

  it("moves the issue in the search index and on both boards", async () => {
    const source = await newProject(tenant, "index-source", "IXS");
    const dest = await newProject(tenant, "index-dest", "IXD");
    const issue = await createIn(tenant, source.id, "Relocation marker zeta");

    await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: dest.id,
    });

    const search = (projectId: ProjectId) =>
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "Relocation marker",
        kinds: ["issue"],
        projectId,
        limit: 25,
        cursor: null,
      });
    const boardIds = async (projectId: ProjectId) =>
      (await issueService.getBoard(tenant.actors.member, tenant.org.id, projectId))
        .flatMap((column) => column.issues.map((row) => row.id));

    expect((await search(dest.id)).items.map((hit) => hit.id)).toContain(issue.id);
    expect((await search(source.id)).items.map((hit) => hit.id)).not.toContain(issue.id);
    expect(await boardIds(dest.id)).toContain(issue.id);
    expect(await boardIds(source.id)).not.toContain(issue.id);
  });
});

